-- Monster TP moves, imported from LandSandBoat's sql/mob_skills.sql and
-- sql/mob_skill_lists.sql, with each template's skill_list_id read from the
-- zone's mobs.yaml (tools/import_lsb_mobskills.py).
--
-- A monster gains TP from its own swings and from being hit; at its threshold it
-- spends the bar on one of these moves (world._tick_mob).  The row's animation is
-- the client's mob-skill animation, and aoe 1/2 are self-/target-centred AoE.
ALTER TABLE monster_templates ADD COLUMN skill_list_id INTEGER NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS mob_skills (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  animation INTEGER NOT NULL DEFAULT 0,
  aoe INTEGER NOT NULL DEFAULT 0,
  aoe_radius REAL NOT NULL DEFAULT 0,
  distance REAL NOT NULL DEFAULT 6,
  animation_time INTEGER NOT NULL DEFAULT 2000,
  prepare_time INTEGER NOT NULL DEFAULT 1000,
  valid_targets INTEGER NOT NULL DEFAULT 4,
  flag INTEGER NOT NULL DEFAULT 0,
  param INTEGER NOT NULL DEFAULT 0,
  knockback INTEGER NOT NULL DEFAULT 0,
  primary_sc INTEGER NOT NULL DEFAULT 0,
  secondary_sc INTEGER NOT NULL DEFAULT 0,
  tertiary_sc INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS mob_skill_lists (
  skill_list_id INTEGER NOT NULL,
  mob_skill_id INTEGER NOT NULL,
  skill_list_name TEXT,
  PRIMARY KEY (skill_list_id, mob_skill_id)
);

CREATE INDEX IF NOT EXISTS mob_skill_lists_by_skill ON mob_skill_lists (mob_skill_id);

